import { createFilesystemProvider } from "./providers/filesystem.js";
import { GitSourceProvider } from "./providers/git-provider.js";
import { NpmSourceProvider } from "./providers/npm.js";
import { createWebsiteProvider } from "./providers/website.js";
/** The factory for a configured source kind, or null for a kind akm does not support. */
export function resolveSourceProviderFactory(type) {
    switch (type) {
        case "filesystem":
            return createFilesystemProvider;
        case "git":
            return (config) => new GitSourceProvider(config);
        case "npm":
            return (config) => new NpmSourceProvider(config);
        case "website":
            return createWebsiteProvider;
        default:
            return null;
    }
}
